95	function setAboutHeroSloganSurfaceAlpha(progress: number): void {
96	  const element = getAboutHeroSloganElement();
97	  if (!element) return;
98	  const clampedProgress = Math.max(0, Math.min(1, progress));
99	  const alpha =
