157	function syncSectionTextReveal(
158	  selector: string,
159	  domState: { visible: boolean; timers: number[] },
160	  progress: number,
161	): void {
162	  const shouldShow = progress >= SECTION_TEXT_REVEAL_THRESHOLD;
163	  const shouldHide = !shouldShow && progress < SECTION_TEXT_HIDE_THRESHOLD;
164	  if (!shouldShow && !shouldHide) return;
165	  if (domState.visible === shouldShow) return;
166	  domState.visible = shouldShow;
167	  domState.timers = clearTimers(domState.timers);
168	  const elements = Array.from(document.querySelectorAll<HTMLElement>(selector));
169	  elements.forEach((el, i) => {
170	    const id = window.setTimeout(() => {
171	      el.classList.toggle("is-block-reveal-up", shouldShow);
172	    }, i * SECTION_TEXT_STAGGER_MS);
173	    domState.timers.push(id);
174	  });
175	}
