177	
178	function disposeSectionTextReveal(
179	  selector: string,
180	  domState: { visible: boolean; timers: number[] },
181	): void {
182	  domState.timers = clearTimers(domState.timers);
183	  domState.visible = false;
184	  document
185	    .querySelectorAll<HTMLElement>(selector)
186	    .forEach((el) => el.classList.remove("is-block-reveal-up"));
187	}
