246	function syncAboutContactHead(progress: number): void {
247	  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
248	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
249	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
250	  if (!section || !head || !actions) return;
251	
252	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
253	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
254	
255	  if (aboutSceneDomState.isContactHeadVisible === shouldShow) return;
256	  aboutSceneDomState.isContactHeadVisible = shouldShow;
257	  aboutSceneDomState.contactHeadTimers = clearTimers(
258	    aboutSceneDomState.contactHeadTimers,
259	  );
260	
261	  if (shouldShow) {
262	    section.dataset.active = "true";
263	    head.dataset.active = "true";
264	    actions.dataset.active = "true";
265	    TextReveal.setVisibleOff(textItems);
266	    textItems.forEach((item, index) => {
267	      const timerId = window.setTimeout(() => {
268	        TextReveal.setVisibleOn(item);
269	      }, index * CONTACT_HEAD_TRANSITION.revealStagger * 1000);
270	      aboutSceneDomState.contactHeadTimers.push(timerId);
271	    });
272	    return;
273	  }
274	
275	  textItems.forEach((item) => {
276	    TextReveal.setVisibleOff(item);
277	  });
278	  section.dataset.active = "false";
279	  head.dataset.active = "false";
280	  actions.dataset.active = "false";
281	}
