283	function disposeAboutContactHead(): void {
284	  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
285	  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
286	  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
287	  if (!section || !head || !actions) return;
288	
289	  aboutSceneDomState.isContactHeadVisible = false;
290	  aboutSceneDomState.contactHeadTimers = clearTimers(
291	    aboutSceneDomState.contactHeadTimers,
292	  );
293	  section.dataset.active = "false";
294	  head.dataset.active = "false";
295	  actions.dataset.active = "false";
296	
297	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
298	  textItems.forEach((item) => TextReveal.setVisibleOff(item));
299	}
