394	    if (!force && !this._sampling) return;
395	    const object = this._currentObject;
396	    const scrub = this._recordScrub;
397	    if (!object || !scrub) return;
398	
399	    const now = performance.now();
400	    if (!force && now - this._lastSampleAt < FRAME_MS) return;
401	    this._lastSampleAt = now;
402	
403	    const values = this._readCameraValues();
404	    const cameraProps = object.props.camera;
405	    const cameraScrub = scrub as unknown as AboutTheatreScrubCameraPort;
406	    cameraScrub.capture(({ set }) => {
